func (r *organizationConfigResource) identityOf(m organizationConfigModel) string {
	if v := m.Identity.ValueString(); v != "" {
		return v
	}
	if v := m.ID.ValueString(); v != "" {
		return v
	}
	return ""
}

func (r *organizationConfigResource) refresh(ctx context.Context, identity string, m *organizationConfigModel, diags *diag.Diagnostics, reflected func(map[string]any) bool) bool {
	get := func(ctx context.Context) (map[string]any, bool, error) {
		_ = identity
		res, gerr := r.client.EXO.GetOrganizationConfig(ctx, exo.GetOrganizationConfigParams{})
		if gerr != nil {
			if isNotFound(gerr) {
				return nil, false, nil
			}
			return nil, false, gerr
		}
		o := firstObject(res.Value)
		return o, o != nil, nil
	}
	obj, present, err := resourcex.LoadUntil(ctx, consistency.Config{}, get, reflected)
	if err != nil {
		diags.AddError("Get-OrganizationConfig failed", err.Error())
		return false
	}
	if !present {
		return false
	}
	readOrganizationConfig(ctx, obj, m)
	return true
}

